#pragma once

// The game's random generator: a 256-byte ring of generated bytes read
// through a cursor, refilled from a seed. Reads keep the original's
// quirks at the end of the ring and in ranges.

#include "core/base/types.h"

#define RANDOM_RING_SIZE 256

typedef struct {
    uint32_t seed;
    uint8_t ring[RANDOM_RING_SIZE];
    uint8_t cursor;
} RANDOM_STATE;

extern const RANDOM_STATE *const g_Rng;

// Clears the ring and cursor and restores seed 1.
void Random_Reset(void);

// Keeps the ring and cursor when reseeding.
void Random_Seed(uint32_t seed);
uint16_t Random_U15(void);

// Fills the ring with low generator bytes without resetting its cursor.
void Random_Fill(void);
uint8_t Random_RingU8(void);
uint8_t Random_RingU8And(uint8_t mask);

// Returns the ring word at the cursor and advances one byte; as in retail,
// the last word's high byte is zero instead of wrapping.
uint16_t Random_RingU16(void);

// Returns a ring value in minimum..maximum; as in retail, equal bounds give
// the raw value and descending ones wrap.
uint8_t Random_RingU8Range(uint8_t minimum, uint8_t maximum);
uint16_t Random_RingU16Range(uint16_t minimum, uint16_t maximum);
